F=np.load('feats.npz'); y=F['y']; A=dict(np.load('featsA.npz'))
def stdz(X,tr): mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd
def mkfolds(seed):
    rng=np.random.RandomState(seed); f2=np.zeros(len(y),int)
    for c in range(8):
        idx=np.where(y==c)[0]; rng.shuffle(idx); f2[idx]=np.arange(len(idx))%5
    return f2
FS=[mkfolds(s) for s in [0,7,11,23,99]]
def rcv(C,M,wc,lams):
    out=np.zeros(len(lams))
    for fo in FS:
        for f in range(5):
            tr=fo!=f; te=~tr
            Z=np.concatenate([wc*stdz(C,tr),stdz(M,tr)],1); Z=Z-Z[tr].mean(0)
            K=Z@Z[tr].T; Y=np.eye(8)[y[tr]]-1/8
            ev,U=np.linalg.eigh(K[tr]); UtY=U.T@Y
            for i,l in enumerate(lams):
                a=U@(UtY/(ev+l)[:,None]); out[i]+=(np.argmax(K[te]@a,1)==y[te]).sum()
    return np.round(out/(len(FS)*len(y)),4)
